<?php $pageTitle='Feedback | StudentHub'; require __DIR__.'/includes/header.php'; $msg='';if($_SERVER['REQUEST_METHOD']==='POST'){ $rating=(int)($_POST['rating']??0);$comment=trim($_POST['comment']??'');if($rating<1||$rating>5||strlen($comment)<3)$msg='Select a rating and enter at least three characters.';else{file_put_contents(__DIR__.'/storage/feedback.jsonl',json_encode(['rating'=>$rating,'comment'=>$comment,'created_at'=>date('c')]).PHP_EOL,FILE_APPEND|LOCK_EX);$msg='Thank you. Your feedback was saved locally.';}} ?><h1>Share your feedback</h1><?php if($msg): ?><p class="notice"><?= e($msg) ?></p><?php endif; ?><form class="form" method="post"><div class="field"><label for="rating">Rating</label><select id="rating" name="rating" required><option value="">Choose a rating</option><?php for($i=1;$i<=5;$i++): ?><option value="<?= $i ?>"><?= $i ?> / 5</option><?php endfor; ?></select></div><div class="field"><label for="comment">Your feedback</label><textarea id="comment" name="comment" rows="4" required minlength="3"></textarea></div><button class="button">Submit feedback</button></form><?php require __DIR__.'/includes/footer.php'; ?>
